+function getStringConfigValue(
+  name: string,
+  value: unknown,
+  { required = false }: { required?: boolean } = {}
+): string | undefined {
+  if (value === undefined) {
+    if (required) {
+      throw new Error(`Invalid configurable.${name}: expected a string`);
+    }
+    return undefined;
+  }
+
+  if (value === null || typeof value !== "string") {
+    throw new Error(`Invalid configurable.${name}: expected a string`);
+  }
+
+  return value;
+}
